// ================= v5.23: MONTURAS, MASCOTAS, FIESTAS Y RECUERDOS DE MÉXICO, PERÚ, TRUJILLO, LIMA NORTE Y ESPAÑA =================
// Todo lo que Sergio aceptó de la lista de ideas (sin oficios nuevos):
//  México: caballo charro y vocho propio · xoloitzcuintle, ajolote y chihuahua · Día de Muertos (ofrenda, maquillaje de
//          catrina y catrín) · lucha libre en la Arena (4 máscaras) · trajinera de Xochimilco con mariachi.
//  Perú/Lima: caballo de paso · alpaca, perro sin pelo y cuy con chullo · procesión de octubre con turrón de doña Pepa ·
//          Circuito Mágico del Agua. Lima Norte: vóley y pollada en Comas (baile cumbia).
//  Trujillo: caballito de totora para remar · pelícano · Concurso Nacional de Marinera en el Coliseo · Chan Chan de noche
//          (misterio) · surf en Huanchaco.
//  España: caballo andaluz y Vespa · lince, toro de peluche y gato madrileño · Fallas (montas y quemas tu falla) · San
//          Fermín con gigantes y cabezudos · cine de verano y verbena (chotis) · Camino de Santiago con credencial.
//  Todos: tiendas de recuerdos con muebles típicos para tu casa y álbum de recuerdos.

// ---------- utilidades ----------
const IP = {}; // posiciones guardadas por mapa
function ipRect(M, cx, cy, w, h, r) { const ok = (x, y) => { if (x < 1 || y < 1 || x >= M.w - 1 || y >= M.h - 1) return false; const i = M.I(x, y); if (M.objAt[i] >= 0 || SOLID_T[M.ter[i]]) return false; if (M.lg && (M.lg[i] === LM_G.ROAD || M.lg[i] === LM_G.SEA || M.lg[i] === LM_G2.TRENCH)) return false; return true; };
  for (let d = 0; d <= r; d++) for (let dy = -d; dy <= d; dy++) for (let dx = -d; dx <= d; dx++) { if (Math.max(Math.abs(dx), Math.abs(dy)) !== d) continue; const x0 = cx + dx, y0 = cy + dy; let g = true; for (let y = y0 - h + 1; y <= y0 && g; y++) for (let x = x0; x < x0 + w && g; x++) if (!ok(x, y)) g = false; if (g) return [x0, y0]; } return null; }
const ipObj = (M, f, x, y, o) => { addObj(M, 'furn', x, y, Object.assign({ f, fp: [[0, 0]] }, o || {})); return M.objs[M.objs.length - 1]; };
function ipPut(M, f, cx, cy, w, o) { const p = ipRect(M, cx, cy, w || 1, 1, 18); if (!p) return null; const fp = []; for (let k = 0; k < (w || 1); k++) fp.push([k, 0]); return ipObj(M, f, p[0], p[1], Object.assign({ fp, px: p[0] * 16 + (w || 1) * 8 }, o || {})); }
function ipXact(M, x, y, xact, o) { return ipObj(M, 'lm_vacio', x, y, Object.assign({ solid: false, xact }, o || {})); }
const ipSp = (M, id, x, y, o) => fsSp(M, id, x, y, o);
const ipPoi = (M, c, x, y, t) => fsPoi(M, c, x, y, t);
const ipNight = () => typeof darkness === 'function' ? darkness() > 0.45 : (G.time >= 19 * 60 || G.time < 5 * 60);
function ipNpc(id, n, t, base, g, k, line, cos, patch) { fsNpc(id, n, t, base, g, k, line, cos); if (patch) FS_LOOK[id][3] = patch; }
{ const _na = npcAtlas; npcAtlas = function (id) { const F = FS_LOOK[id]; if (F && F[3]) return getAtlas('IPN' + id, () => { const [b, li, cos, patch] = F, [a, c0] = (b === 'mx' ? mxApp : b === 'pe' ? peApp : esApp)(li), A = Object.assign({}, a, patch), L = heroLook('guerrero', A, { weapon: 0 }, cos || c0 || {}, {}); L.weapon = null; L.back = null; return buildAtlas(L, ['idle', 'walk'], drawHero); }); return _na.apply(this, arguments); }; }
function ipShop(npcId, list) { PE_SELL[npcId] = (PE_SELL[npcId] || []).concat(list.filter(i => ITEMS[i])); }

